<script setup>
import { computed, onMounted, ref } from 'vue';
import { useRoute } from 'vue-router';
import axios from 'axios';
import AppIcon from '../components/base/AppIcon.vue';
import GameKitExpiredState from '../components/gamekit/GameKitExpiredState.vue';

const route = useRoute(); const MAX_MISSES = 12; const session = ref(null), loading = ref(true), error = ref(''), wordIndex = ref(0), guessed = ref([]), misses = ref(0), completed = ref(0), finished = ref(false), revealed = ref(false); const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split(''); const currentWord = computed(() => session.value?.words?.[wordIndex.value] ?? ''); const normalized = (letter) => letter.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase(); const displayWord = computed(() => currentWord.value.split('').map(letter => letter === ' ' ? ' ' : revealed.value || guessed.value.includes(normalized(letter)) ? letter.toUpperCase() : '_').join(' ')); const solved = computed(() => currentWord.value && currentWord.value.split('').filter(l => l !== ' ').every(l => guessed.value.includes(normalized(l)))); const failed = computed(() => misses.value >= MAX_MISSES); const advance = async () => { if (wordIndex.value + 1 >= session.value.words.length) { finished.value = true; await sendResult(); return; } wordIndex.value++; guessed.value = []; misses.value = 0; revealed.value = false; }; const guess = async (letter) => { if (finished.value || failed.value || guessed.value.includes(letter)) return; guessed.value.push(letter); if (!currentWord.value.split('').some(l => normalized(l) === letter)) misses.value++; if (solved.value) { completed.value++; await advance(); } else if (misses.value >= MAX_MISSES) revealed.value = true; }; const sendResult = async () => { try { await axios.post('/api/gamekit/hangman/play/' + route.params.token + '/result', { completed_words: completed.value, misses: misses.value, completed: true }); } catch { /* resultado local permanece */ } }; onMounted(async () => { try { session.value = (await axios.get('/api/gamekit/hangman/play/' + route.params.token)).data.session; } catch { error.value = 'Esta atividade não está mais disponível.'; } finally { loading.value = false; } });
</script>
<template><main class="min-h-screen bg-[#f4f6f3] px-4 py-8 sm:px-6 sm:py-12"><section class="mx-auto w-full max-w-2xl"><div v-if="loading" class="rounded-3xl bg-white p-12 text-center">Carregando jogo...</div><GameKitExpiredState v-else-if="error" :message="error" /><div v-else class="space-y-5"><header class="rounded-3xl bg-white p-6 text-center shadow-sm sm:p-8"><span class="mx-auto flex size-14 items-center justify-center rounded-2xl bg-[var(--spa-accent-soft)] text-[var(--spa-accent)]"><AppIcon name="Languages" class="size-7" /></span><p class="section-kicker mt-4">{{ session.theme }}</p><h1 class="mt-1 text-2xl font-semibold text-[var(--spa-ink)]">{{ session.name }}</h1><p class="mt-2 text-sm text-[var(--spa-ink-muted)]">Palavra {{ Math.min(wordIndex + 1, session.words.length) }} de {{ session.words.length }}</p></header><section v-if="!finished" class="rounded-3xl bg-white p-6 text-center shadow-sm sm:p-8"><div class="mx-auto mb-5 flex h-48 w-48 items-center justify-center rounded-3xl bg-[var(--spa-surface-muted)]"><svg viewBox="0 0 160 190" class="h-44 w-40" aria-label="Boneco da forca"><g fill="none" stroke="#526b5c" stroke-linecap="round" stroke-linejoin="round" stroke-width="7"><path v-if="misses >= 1" d="M20 175h120"/><path v-if="misses >= 2" d="M48 175V20"/><path v-if="misses >= 3" d="M48 20h74"/><path v-if="misses >= 4" d="M122 20v24"/><circle v-if="misses >= 5" cx="122" cy="63" r="19" fill="#edf4ef"/><circle v-if="misses >= 6" cx="115" cy="60" r="2.5" fill="#526b5c" stroke="none"/><circle v-if="misses >= 7" cx="129" cy="60" r="2.5" fill="#526b5c" stroke="none"/><path v-if="misses >= 8" d="M122 82v48"/><path v-if="misses >= 9" d="M122 94l-28 25"/><path v-if="misses >= 10" d="M122 94l28 25"/><path v-if="misses >= 11" d="M122 130l-25 40"/><path v-if="misses >= 12" d="M122 130l25 40"/></g></svg></div><p class="text-4xl font-bold tracking-[0.4em] text-[var(--spa-ink)] sm:text-5xl">{{ displayWord }}</p><p class="mt-4 text-sm text-[var(--spa-ink-muted)]">{{ failed ? 'A palavra era:' : `Erros nesta palavra: ${misses} de ${MAX_MISSES}` }}</p><button v-if="failed" class="btn-primary mx-auto mt-4" type="button" @click="advance">{{ wordIndex + 1 >= session.words.length ? 'Finalizar' : 'Ver próxima palavra' }}</button><div class="mx-auto mt-7 grid max-w-xl grid-cols-7 gap-2 sm:grid-cols-9"><button v-for="letter in alphabet" :key="letter" class="aspect-square rounded-xl border border-[var(--spa-border)] bg-[var(--spa-surface-muted)] text-sm font-bold text-[var(--spa-ink)] transition hover:border-[var(--spa-accent)] disabled:cursor-default disabled:opacity-40" :disabled="guessed.includes(letter) || failed" type="button" @click="guess(letter)">{{ letter }}</button></div></section><section v-else class="rounded-3xl bg-white p-8 text-center shadow-sm"><AppIcon name="CircleCheck" class="mx-auto size-12 text-emerald-600" /><h2 class="mt-4 text-2xl font-semibold text-[var(--spa-ink)]">Atividade concluída!</h2><p class="mt-2 text-sm text-[var(--spa-ink-muted)]">Você descobriu {{ completed }} de {{ session.words.length }} palavras.</p></section></div></section></main></template>
